    .btn:hover { transform: translateY(-1px); }
    .btn-primary {
      background: var(--primary);
      color: #fff;
      box-shadow: 0 8px 20px rgba(0, 102, 255, .24);
    }
    .btn-primary:hover { background: var(--primary-dark); }
    .btn-accent {
      background: var(--accent);
