      box-shadow: 0 8px 20px rgba(21, 184, 166, .22);
    }
    .btn-accent:hover { background: var(--accent-dark); }
    .btn-ghost {
      background: transparent;
      border: 1px solid var(--line);
      color: #1e293b;
    }

    .hamburger {
      display: none;
      border: 1px solid var(--line);
      background: white;
      border-radius: 10px;
      width: 42px;
      height: 42px;
      cursor: pointer;
