      .hamburger { display: inline-flex; }
      .hero { padding: 60px 0 40px; text-align: left; }
      .hero p { margin-left: 0; }
      section { padding: 60px 0; }
      .stats, .steps, .testimonials-grid, .specialty-grid, .footer-grid { grid-template-columns: 1fr; }
