          <div class="field">
            <svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M11 19a8 8 0 1 1 0-16 8 8 0 0 1 0 16Z" stroke="currentColor" stroke-width="2"/><path d="m21 21-4.35-4.35" stroke="currentColor" stroke-width="2"/></svg>
            <input id="queryInput" name="q" type="text" autocomplete="off" placeholder="Search specialty, doctor name, or condition" aria-label="Search providers" />
