        <a class="specialty-card" href="search-results.html?specialty=Primary%20Care"><span class="icon">🩺</span><strong>Primary Care</strong></a>
        <a class="specialty-card" href="search-results.html?specialty=Dentist"><span class="icon">🦷</span><strong>Dentist</strong></a>
