  <script>
    const suggestions = [
      { value: 'Primary Care', hint: 'Specialty' },
      { value: 'Dentist', hint: 'Specialty' },
      { value: 'Dermatologist', hint: 'Specialty' },
      { value: 'Psychiatrist', hint: 'Specialty' },
      { value: 'Eye Doctor', hint: 'Specialty' },
      { value: 'Orthopedic Surgeon', hint: 'Specialty' },
      { value: 'Anxiety', hint: 'Condition' },
      { value: 'Back pain', hint: 'Condition' },
      { value: 'Dr. Sarah Chen', hint: 'Provider' }
    ];

    const queryInput = document.getElementById('queryInput');
    const autocomplete = document.getElementById('autocomplete');
    let activeIndex = -1;

    function renderSuggestions(items) {
      if (!items.length) {
        autocomplete.classList.remove('open');
        autocomplete.innerHTML = '';
        return;
      }
      autocomplete.innerHTML = items.map((item, i) =>
        `<button type="button" class="suggestion ${i === activeIndex ? 'active' : ''}" data-value="${item.value}">${item.value}<br><span>${item.hint}</span></button>`
      ).join('');
      autocomplete.classList.add('open');
    }

    function filterSuggestions(term) {
      const t = term.trim().toLowerCase();
      if (!t) return suggestions.slice(0, 6);
      return suggestions.filter(s => s.value.toLowerCase().includes(t)).slice(0, 6);
    }

    queryInput.addEventListener('input', (e) => {
      activeIndex = -1;
      renderSuggestions(filterSuggestions(e.target.value));
    });

    queryInput.addEventListener('focus', () => {
      renderSuggestions(filterSuggestions(queryInput.value));
    });

    queryInput.addEventListener('keydown', (e) => {
      const items = [...autocomplete.querySelectorAll('.suggestion')];
      if (!items.length) return;
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        activeIndex = (activeIndex + 1) % items.length;
        renderSuggestions(filterSuggestions(queryInput.value));
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        activeIndex = (activeIndex - 1 + items.length) % items.length;
        renderSuggestions(filterSuggestions(queryInput.value));
      } else if (e.key === 'Enter' && activeIndex >= 0) {
        e.preventDefault();
        queryInput.value = items[activeIndex].dataset.value;
        autocomplete.classList.remove('open');
      } else if (e.key === 'Escape') {
        autocomplete.classList.remove('open');
      }
    });

    autocomplete.addEventListener('click', (e) => {
      const btn = e.target.closest('.suggestion');
      if (!btn) return;
      queryInput.value = btn.dataset.value;
      autocomplete.classList.remove('open');
      queryInput.focus();
    });

    document.addEventListener('click', (e) => {
      if (!e.target.closest('.field')) autocomplete.classList.remove('open');
    });

    document.getElementById('searchForm').addEventListener('submit', (e) => {
      if (!queryInput.value.trim()) {
        e.preventDefault();
        queryInput.focus();
      }
    });

    const menuBtn = document.getElementById('menuBtn');
    const mobileDrawer = document.getElementById('mobileDrawer');
    const mobileOverlay = document.getElementById('mobileOverlay');
    const closeMenu = document.getElementById('closeMenu');

    function toggleMenu(open) {
      mobileDrawer.classList.toggle('open', open);
      mobileOverlay.classList.toggle('open', open);
      menuBtn.setAttribute('aria-expanded', String(open));
    }

    menuBtn.addEventListener('click', () => toggleMenu(true));
    closeMenu.addEventListener('click', () => toggleMenu(false));
    mobileOverlay.addEventListener('click', () => toggleMenu(false));
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') toggleMenu(false);
    });
  </script>
</body>
